/**
 * 💡 THOUGHT PROCESS:
 * Every signal-colored badge in this app -- sentiment tags, impact levels, status pills, regime
 * pills -- used to be its own hand-rolled `Surface(color = pillColor) { Text(color = textColor) }`,
 * each with its own slightly different padding. Changing "how big is a signal pill" or "what color
 * is its text" meant hunting down every one of those call sites individually. This collapses that
 * down to one component, the same reasoning as `PulseCard` for card outer styles.
 *
 * Text color is deliberately blended here, not at the token level (`PulseColors.signalBullishText`
 * etc. stay exactly as they are) -- those tokens are also used as plain standalone text (VIX's
 * "GREED"/"FEAR" status label, for instance), where the fuller-strength color is correct. The blend
 * is specifically a pill thing: sitting on top of the pill's own tinted fill, the full-strength text
 * needed adjusting, so it only happens here, at the one place a signal color is used as pill content.
 *
 * The direction flips per mode, not just the amount: in light mode the signal tokens are dark-on-
 * light (e.g. bullish text is a dark green), and blending those toward white read as too soft against
 * the light pill fill, so light mode blends toward black instead, deliberately more assertive ("make
 * the pill text darker" with no "a little bit" qualifier). Dark mode's tokens are already fairly
 * light (bullish text is closer to a light green already), so it only needs a modest further blend
 * toward white ("a little bit lighter"). Read off `colorScheme.background`'s luminance rather than a
 * new token, since every preset's own light/dark identity already lives there.
 *
 * `leadingIcon` is an optional slot (not a fixed icon param) so this same component can back both a
 * plain text pill (a sentiment tag) and an icon+text one (`DirectionalChangePill`'s triangle) without
 * two near-duplicate implementations. `trailingIcon`/`onClick` are the same idea, symmetrical on the
 * other side -- a pill that's itself a tap target to open more detail (e.g. a glossary sheet scoped
 * to just that term) gets a trailing chevron without a second, near-duplicate "clickable pill"
 * component. Both default to null/no-op, so every existing call site is unaffected.
 *
 * `outlined` (added for the Indicators domain's alignment/agreement/shift-direction states) swaps
 * the solid tinted fill for a transparent fill + a `border_thin` stroke -- a lighter-weight
 * treatment for a state that's supporting context next to a card's main content, not the card's
 * own primary data pill (which stays filled). The stroke uses `contentColor`, not `pillColor` --
 * `pillColor` is a deliberately pale background-tint token meant to sit *behind* bright text, so
 * even at a hairline width it reads as washed-out against the card background; `contentColor` is
 * the saturated foreground-strength token these signal colors already use for plain text, and
 * reads clearly as a ring at `border_thin` once it's the stroke color doing the work rather than
 * the width. Text uses `contentColor` at full strength too, rather than the light/dark blend below,
 * since it's no longer sitting on top of a strong tinted fill that needed correcting for.
 */
@Composable
fun SignalPill(
    text: String,
    pillColor: Color,
    contentColor: Color,
    modifier: Modifier = Modifier,
    outlined: Boolean = false,
    leadingIcon: (@Composable () -> Unit)? = null,
    trailingIcon: (@Composable () -> Unit)? = null,
    onClick: (() -> Unit)? = null
) {
    val isLightMode = MaterialTheme.colorScheme.background.luminance() > 0.5f
    val pillTextColor = when {
        outlined -> contentColor
        isLightMode -> lerp(contentColor, Color.Black, 0.2f)
        else -> lerp(contentColor, Color.White, .4f)
    }

    Surface(
        color = if (outlined) Color.Transparent else pillColor,
        border = if (outlined) BorderStroke(dimensionResource(id = R.dimen.border_thin), contentColor) else null,
        shape = RoundedCornerShape(dimensionResource(id = R.dimen.corner_radius_pill)),
        modifier = if (onClick != null) modifier.clickable(onClick = onClick) else modifier
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            modifier = Modifier.padding(
                horizontal = dimensionResource(id = R.dimen.padding_medium),
                vertical = dimensionResource(id = R.dimen.padding_small)
            )
        ) {
            leadingIcon?.let {
                it()
                Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_tiny)))
            }
            Text(
                text = text,
                style = MaterialTheme.typography.labelMedium.copy(fontWeight = FontWeight.Bold),
                color = pillTextColor
            )
            trailingIcon?.let {
                Spacer(modifier = Modifier.width(dimensionResource(id = R.dimen.padding_tiny)))
                it()
            }
        }
    }
}

